/// Enumerator name for `ty` = `value`.
pub fn name(ty: &str, value: i32) -> Option<&'static str> {
    let idx = ENUMS.binary_search_by_key(&ty, |(n, _)| n).ok()?;
    ENUMS[idx]
        .1
        .iter()
        .find(|(_, v)| *v == value)
        .map(|(n, _)| *n)
}

/// Value for an enumerator name (case-sensitive).
pub fn value(ty: &str, enumerator: &str) -> Option<i32> {
    let idx = ENUMS.binary_search_by_key(&ty, |(n, _)| n).ok()?;
    ENUMS[idx]
        .1
        .iter()
        .find(|(n, _)| *n == enumerator)
        .map(|(_, v)| *v)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn table_is_sorted_and_resolves_known_values() {
        assert!(ENUMS.windows(2).all(|w| w[0].0 < w[1].0));
        assert_eq!(name("gEItemCategory", 1), Some("Weapon"));
        assert_eq!(name("gEDamageType", 2), Some("Blade"));
        assert_eq!(value("gEClass", "Warrior"), Some(3));
        assert_eq!(name("gEItemCategory", 99), None);
        assert_eq!(name("NoSuchEnum", 0), None);
    }
}
